  const xMax = Core_Cartesian3.clone(currentPos, fromPointsXMax);
  const yMax = Core_Cartesian3.clone(currentPos, fromPointsYMax);
  const zMax = Core_Cartesian3.clone(currentPos, fromPointsZMax);
