  const xSpan = Core_Cartesian3.magnitudeSquared(Core_Cartesian3.subtract(xMax, xMin, fromPointsScratch));
  const ySpan = Core_Cartesian3.magnitudeSquared(Core_Cartesian3.subtract(yMax, yMin, fromPointsScratch));
  const zSpan = Core_Cartesian3.magnitudeSquared(Core_Cartesian3.subtract(zMax, zMin, fromPointsScratch));

